function bindFields(root){root.querySelectorAll('[data-path]').forEach(el=>el.addEventListener('input',()=>{editPath(el.dataset.path,el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):typeof getPath(draft,el.dataset.path)==='number'?Number(el.value):el.value);if(el.dataset.path==='settings.mode'){if(draft.settings.mode==='campaign'&&draft.settings.runs>1000)draft.settings.runs=100;markDirty();if($('#dialog').open)settingsModal();else render()}}));root.querySelectorAll('[data-count]').forEach(el=>el.onchange=()=>{runs=Number(el.value)});root.querySelectorAll('[data-equipment]').forEach(el=>el.onchange=()=>{const slot=el.dataset.equipment;draft.build.itemIds=draft.build.itemIds.filter(id=>draft.items.find(i=>i.id===id)?.slot!==slot);if(el.value)draft.build.itemIds.push(el.value);markDirty();updateInspector()});root.querySelectorAll('[data-deck]').forEach(el=>el.oninput=()=>{const id=el.dataset.deck,n=Number(el.value);draft.build.deck=draft.build.deck.filter(x=>x.cardId!==id);if(n>0)draft.build.deck.push({cardId:id,count:n});markDirty();updateInspector()});root.querySelectorAll('[data-rpg-group]').forEach(el=>el.oninput=()=>{const id=el.dataset.rpgGroup,n=Number(el.value);draft.group=draft.group.filter(x=>x.enemyId!==id);if(n>0)draft.group.push({enemyId:id,count:n});markDirty()});root.querySelectorAll('[data-encounter-enemy]').forEach(el=>el.oninput=()=>{const o=currentObject(),id=el.dataset.encounterEnemy,n=Number(el.value);o.enemies=o.enemies.filter(x=>x.enemyId!==id);if(n>0)o.enemies.push({enemyId:id,count:n});markDirty()})}
function bind(){bindStudyForm();bindFields($('#main'));const mk=$('#mobile-kind');if(mk)mk.onchange=()=>applyNavigation({type,view:'design',kind:mk.value});const mo=$('#mobile-object');if(mo)mo.onchange=()=>{selected=mo.value;render()};const form=$('#editor-form');if(form)form.onsubmit=e=>{e.preventDefault();try{saveDesign('编辑 '+(currentObject()?.name||KIND[type][kind]));if(e.submitter?.value==='run')run();else{render();toast('设计已保存，可继续运行验证')}}catch(error){toast(error.message)}};const range=$('#trace-range');if(range)range.oninput=()=>{stop();traceStep=Number(range.value);render();scrollEvent()};const stage=$('#trace-stage');if(stage)stage.onchange=()=>{stop();traceIndex=Number(stage.value);traceStep=0;render()};const rng=$('#trace-rng');if(rng)rng.onchange=()=>{stop();traceRng=rng.checked;traceStep=0;render()};const speed=$('#trace-speed');if(speed)speed.onchange=()=>{traceSpeed=Number(speed.value);stop();render()};const query=$('#asset-query');if(query)query.oninput=()=>{assetQuery=query.value;const pos=query.selectionStart;render();$('#asset-query').focus();$('#asset-query').setSelectionRange(pos,pos)};const cat=$('#asset-category');if(cat)cat.onchange=()=>{assetCategory=cat.value;render()};const saved=$('#asset-saved');if(saved)saved.onchange=()=>{assetSaved=saved.checked;render()}}
$('#import-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>2e6)throw Error('文件超过 2 MB');importPreview(JSON.parse(await f.text()),f.name)}catch(error){toast('导入失败：'+error.message)}finally{e.target.value=''}};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();try{Promise.resolve(actions[b.dataset.action]?.(b)).catch(error=>toast(error.message))}catch(error){toast(error.message)}});
addEventListener('hashchange',()=>requestNavigation(routeValue(location.hash)));
addEventListener('storage',e=>{if(e.key===KEYS[type]){blocked=true;render();toast('另一窗口更新了当前设计，请导出草稿后刷新')}if(e.key==='ptu.cardlab.assets'&&view==='assets')render();if(e.key==='ptu.cardlab.config'){classic=null;classicConfig=null;if(view==='play'&&playMode==='classic')render()}});
