document.addEventListener('keydown',e=>{if(e.isComposing)return;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();searchModal()}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();try{saveDesign();render();toast('设计已保存')}catch(error){toast(error.message)}}if((e.metaKey||e.ctrlKey)&&e.key==='Enter'){e.preventDefault();if($('#dialog').open)return;if(view==='start'){if(studyForm)runComparison();else openCurrentStudy()}else run()}if(e.key==='Escape')stop()});
const initial=routeValue(location.hash),legacyTab=new URL(location.href).searchParams.get('tab');type=initial.type;view=initial.view;kind=initial.kind||(type==='cards'?'cards':Object.keys(KIND[type])[0]);if(legacyTab==='play'){type='cards';view='play';playMode='classic'}else if(legacyTab==='assets')view='assets';load(type);if(!Object.hasOwn(KIND[type],kind))kind=Object.keys(KIND[type])[0];applyNavigation({type,view,kind});
const token=new URL(location.href).searchParams.get('handoff');if(token){try{const transfer=JSON.parse(localStorage.getItem('pt.gss.cardlab.handoff.v1')||'null');if(!transfer||transfer.token!==token||Date.now()-transfer.createdAt>600000)throw Error('传入牌组已过期，请从原沙盘重新发送');importPreview(transfer.data,'Card Lab 牌组')}catch(error){toast(error.message)}}
